svg_shape_error svg_clip_resolve(base_bytes source, const svg_xml_token *tokens,
                                 size_t token_count,
                                 svg_reference_index *references,
                                 svg_css_sheet *css,
                                 svg_xml_span value,
                                 svg_shape_document *document,
                                 size_t *document_clip_bytes,
                                 geom_affine user_inverse,
                                 const double local_bounds[4],
                                 size_t owner_node,
                                 svg_shape_clip **out,
                                 svg_shape_diagnostic *diagnostic)
{
    if (out == NULL || document == NULL || document_clip_bytes == NULL ||
        css == NULL ||
        local_bounds == NULL) {
        if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_INVALID_ARGUMENT, value.offset};
        return SVG_SHAPE_ERROR_INVALID_ARGUMENT;
    }
    *out = NULL;
    uint8_t *rule_by_offset = NULL;
    svg_xml_span id;
    if (!parse_reference(source, value, &id)) goto unsupported;
    size_t target;
    if (!svg_reference_index_find(source, tokens, token_count, references,
                                  id, &target) ||
        !eq(source, tokens[target].local_name, "clipPath") ||
        tokens[target].prefix.length != 0U) goto unsupported;
    if (attr(source, tokens, token_count, target, "clip-path", &id) ||
        attr(source, tokens, token_count, target, "transform", &id) ||
        attr(source, tokens, token_count, target, "style", &id)) goto unsupported;
    bool object_box = false;
    svg_xml_span units;
    bool has_units = attr(source, tokens, token_count, target, "clipPathUnits", &units);
    if (has_units) {
        if (eq(source, units, "userSpaceOnUse")) object_box = false;
        else if (eq(source, units, "objectBoundingBox")) object_box = true;
        else goto unsupported;
    }
    size_t end_token = element_end(tokens, token_count, target);
    size_t child_start = tokens[target].source.offset + tokens[target].source.length;
    size_t child_end = end_token == target ? child_start : tokens[end_token].source.offset;
    if (child_start > child_end || child_end > source.len) goto unsupported;
    size_t child_length = child_end - child_start;
    if (child_length > CLIP_MAX_REFERENCE_BYTES) goto limit;
    if (child_length == 0U) goto unsupported;
    rule_by_offset = svg_shape_calloc(child_length, sizeof(*rule_by_offset));
    if (rule_by_offset == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, value.offset};
        return SVG_SHAPE_ERROR_OOM;
    }
    svg_shape_error style_error = clip_rule_map(
        css, source, tokens, token_count, target, end_token, child_start,
        child_length, rule_by_offset, diagnostic);
    if (style_error != SVG_SHAPE_ERROR_NONE) {
        svg_shape_free(rule_by_offset);
        return style_error;
    }
    size_t child_count = 0U;
    for (size_t i = target + 1U; i < end_token; ++i) {
        if ((tokens[i].kind == SVG_XML_TOKEN_START_ELEMENT ||
             tokens[i].kind == SVG_XML_TOKEN_EMPTY_ELEMENT) &&
            tokens[i].depth == tokens[target].depth + 1U) {
            if (++child_count > CLIP_MAX_CHILDREN ||
                attr(source, tokens, token_count, i, "clip-path", &units)) goto limit;
        }
    }
    if (child_count == 0U) goto unsupported;
    /* The prefix permits 191 payload bytes; suffix and NUL count in scratch. */
    char prefix_pattern[CLIP_WRAPPER_BUFFER_BYTES];
    int prefix_result = object_box
        ? snprintf(prefix_pattern, sizeof(prefix_pattern),
                   "<svg width=\"1\" height=\"1\" viewBox=\"0 0 1 1\">")
        : snprintf(prefix_pattern, sizeof(prefix_pattern),
                   "<svg width=\"%u\" height=\"%u\" viewBox=\"%.17g %.17g %.17g %.17g\">",
                   document->width, document->height, document->view_x,
                   document->view_y, document->view_width, document->view_height);
    if (prefix_result < 0 || (size_t)prefix_result >= sizeof(prefix_pattern)) goto limit;
    size_t prefix_length = (size_t)prefix_result;
    static const char suffix[] = "</svg>";
    if (prefix_length > SIZE_MAX - sizeof(suffix) - child_length) goto limit;
    size_t total = prefix_length + child_length + sizeof(suffix) - 1U;
    if (total >= CLIP_MAX_JOB_REFERENCE_BYTES) goto limit;
    size_t allocation_bytes = total + 1U;
    if (*document_clip_bytes > CLIP_MAX_JOB_REFERENCE_BYTES - allocation_bytes)
        goto limit;
    uint8_t *scratch = svg_shape_malloc(allocation_bytes);
    svg_shape_clip *clip = svg_shape_calloc(1U, sizeof(*clip));
    if (scratch == NULL || clip == NULL) {
        svg_shape_free(scratch); svg_shape_free(clip);
        svg_shape_free(rule_by_offset);
        if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, value.offset};
        return SVG_SHAPE_ERROR_OOM;
    }
    (void)svg_shape_alloc_set_tag(scratch, SVG_SHAPE_ALLOC_TAG_CLIP_COPY);
    memcpy(scratch, prefix_pattern, prefix_length);
    memcpy(scratch + prefix_length, source.ptr + child_start, child_length);
    memcpy(scratch + prefix_length + child_length, suffix, sizeof(suffix) - 1U);
    scratch[total] = 0U;
    clip->source = scratch;
    clip->source_length = total;
    clip->owner_node = owner_node;
    clip->references = 1U;
    clip->object_bounding_box = object_box;
    clip->user_inverse = user_inverse;
    memcpy(clip->bounds, local_bounds, sizeof(clip->bounds));
    if (object_box && (clip->bounds[2] <= clip->bounds[0] ||
                       clip->bounds[3] <= clip->bounds[1])) {
        svg_clip_destroy(clip); goto unsupported;
    }
    svg_shape_error error = svg_shape_decode((base_bytes){scratch, total}, &clip->geometry, diagnostic);
    if (error != SVG_SHAPE_ERROR_NONE) {
        if (diagnostic != NULL) {
            size_t generated = diagnostic->offset;
            diagnostic->offset = generated >= prefix_length &&
                generated - prefix_length < child_length
                ? child_start + generated - prefix_length : value.offset;
        }
        svg_clip_destroy(clip);
        svg_shape_free(rule_by_offset);
        return error;
    }
    if (clip->geometry.edge_count > CLIP_MAX_EDGES) {
        svg_clip_destroy(clip); goto limit;
    }
    for (size_t shape = 0U; shape < clip->geometry.shape_count; ++shape) {
        size_t offset = clip->geometry.shape_sources[shape].offset;
        if (offset < prefix_length || offset - prefix_length >= child_length) {
            svg_clip_destroy(clip); goto unsupported;
        }
        clip->geometry.shape_evenodd[shape] =
            rule_by_offset[offset - prefix_length] != 0U;
    }
    svg_shape_free(rule_by_offset);
    *document_clip_bytes += allocation_bytes;
    document->has_clips = true;
    *out = clip;
    return SVG_SHAPE_ERROR_NONE;
limit:
    svg_shape_free(rule_by_offset);
    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, value.offset};
    return SVG_SHAPE_ERROR_LIMIT;
unsupported:
    svg_shape_free(rule_by_offset);
    if (diagnostic != NULL) *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_UNSUPPORTED, value.offset};
    return SVG_SHAPE_ERROR_UNSUPPORTED;
}

bool svg_clip_contains(const svg_shape_clip *clip, double x, double y)
{
    if (clip == NULL) return true;
    double root_x = x, root_y = y;
    geom_point local;
    if (!geom_affine_map_point(clip->user_inverse, (geom_point){x, y}, &local))
        return false;
    x = local.x;
    y = local.y;
    if (clip->object_bounding_box) {
        if (clip->bounds[2] <= clip->bounds[0] ||
            clip->bounds[3] <= clip->bounds[1]) return false;
        x = (x - clip->bounds[0]) / (clip->bounds[2] - clip->bounds[0]);
        y = (y - clip->bounds[1]) / (clip->bounds[3] - clip->bounds[1]);
    }
    bool inside = false;
    for (size_t i = 0U; i < clip->geometry.shape_count; ++i) {
        if (clip->geometry.shape_filled[i] && point_inside(&clip->geometry, i, x, y)) {
            inside = true;
            break;
        }
        }
    }
    return inside && svg_clip_contains(clip->parent, root_x, root_y);
}

static bool clip_local_to_document(const svg_shape_clip *clip,
                                   geom_affine local_to_document,
                                   geom_point point, geom_point *out)
{
    if (clip->object_bounding_box) {
        point.x = clip->bounds[0] + point.x *
                  (clip->bounds[2] - clip->bounds[0]);
        point.y = clip->bounds[1] + point.y *
                  (clip->bounds[3] - clip->bounds[1]);
    }
    return geom_affine_map_point(local_to_document, point, out);
}

bool svg_clip_visit_boundary_edges(const svg_shape_clip *clip,
                                   svg_clip_boundary_edge_visitor visitor,
                                   void *context, bool *mapping_valid)
{
    if (mapping_valid != NULL) *mapping_valid = true;
    if (visitor == NULL) return false;
    for (const svg_shape_clip *current = clip; current != NULL;
         current = current->parent) {
        geom_affine local_to_document;
        if (!svg_shape_affine_inverse(current->user_inverse,
                                      &local_to_document)) {
            if (mapping_valid != NULL) *mapping_valid = false;
            return true;
        }
        const svg_shape_document *geometry = &current->geometry;
        for (size_t shape = 0U; shape < geometry->shape_count; shape++) {
            if (!geometry->shape_filled[shape]) continue;
            size_t first = geometry->shape_edge_start[shape];
            size_t end = first + geometry->shape_edge_count[shape];
            for (size_t edge_index = first; edge_index < end; edge_index++) {
                geom_edge edge = geometry->edges[edge_index];
                if (!clip_local_to_document(current, local_to_document,
                                            edge.a, &edge.a) ||
                    !clip_local_to_document(current, local_to_document,
                                            edge.b, &edge.b)) {
                    if (mapping_valid != NULL) *mapping_valid = false;
                    return true;
                }
                if (!visitor(context, edge)) return false;
            }
        }
    }
    return true;
}

bool svg_clip_boundary_work_counts(const svg_shape_clip *clip,
                                   svg_clip_work_counts *out)
{
    if (out == NULL) return false;
    *out = (svg_clip_work_counts){0};
    for (const svg_shape_clip *current = clip; current != NULL;
         current = current->parent) {
        if (out->chain_elements == SIZE_MAX ||
            current->geometry.shape_count > SIZE_MAX - out->child_shapes ||
            current->geometry.edge_count > SIZE_MAX - out->edges) return false;
        out->chain_elements++;
        out->child_shapes += current->geometry.shape_count;
        out->edges += current->geometry.edge_count;
    }
    return true;
}

size_t svg_clip_work_units(const svg_shape_clip *clip)
{
    svg_clip_work_counts counts;
    if (!svg_clip_boundary_work_counts(clip, &counts) ||
        counts.child_shapes > SIZE_MAX - counts.chain_elements) return SIZE_MAX;
    size_t units = counts.chain_elements + counts.child_shapes;
    if (counts.edges > SIZE_MAX - units) return SIZE_MAX;
    return units + counts.edges;
}

void svg_clip_destroy(svg_shape_clip *clip)
{
    if (clip == NULL) return;
    if (clip->references > 1U) { clip->references--; return; }
    svg_shape_clip *parent = clip->parent;
    svg_shape_document_destroy(&clip->geometry);
    svg_shape_free(clip->source);
    svg_shape_free(clip);
    svg_clip_destroy(parent);
}

bool svg_clip_retain(svg_shape_clip *clip)
{
    if (clip == NULL || clip->references == SIZE_MAX) return false;
    clip->references++;
    return true;
}

static bool clone_bytes(size_t count, size_t stride, size_t *bytes)
{
    if (count != 0U && stride > SIZE_MAX / count) return false;
    *bytes = count * stride;
    return true;
}

static bool clone_array(const void *source, size_t count, size_t stride,
                        size_t *total, bool *limit, void **out)
{
    size_t bytes = 0U;
    if (!clone_bytes(count, stride, &bytes) ||
        bytes > CLIP_CLONE_MAX_BYTES - *total) {
        *limit = true;
        return false;
    }
    if (bytes == 0U) {
        *out = NULL;
        return true;
    }
    void *copy = svg_shape_malloc(bytes);
    if (copy == NULL) return false;
    memcpy(copy, source, bytes);
    *total += bytes;
    *out = copy;
    return true;
}

static svg_shape_clip *clone_clip_chain(const svg_shape_clip *source,
                                        size_t depth, size_t *total,
                                        bool *limit)
{
    if (source == NULL || total == NULL || limit == NULL ||
        depth >= CLIP_CLONE_MAX_DEPTH) {
        if (limit != NULL) *limit = true;
        return NULL;
    }
    if (sizeof(svg_shape_clip) > CLIP_CLONE_MAX_BYTES - *total) {
        *limit = true;
        return NULL;
    }
    svg_shape_clip *copy = svg_shape_calloc(1U, sizeof(*copy));
    if (copy == NULL) return NULL;
    *total += sizeof(*copy);
    copy->references = 1U;
    copy->owner_node = source->owner_node;
    copy->owner_before_suffix = source->owner_before_suffix;
    copy->object_bounding_box = source->object_bounding_box;
    copy->user_inverse = source->user_inverse;
    memcpy(copy->bounds, source->bounds, sizeof(copy->bounds));
    if (!clone_array(source->source, source->source_length, 1U, total, limit,
                     (void **)&copy->source)) goto fail;
    copy->source_length = source->source_length;
    svg_shape_document *dst = &copy->geometry;
    const svg_shape_document *src = &source->geometry;
    dst->shape_count = src->shape_count;
    dst->edge_count = src->edge_count;
    if (!clone_array(src->edges, src->edge_count, sizeof(*src->edges), total, limit,
                     (void **)&dst->edges) ||
        !clone_array(src->shape_evenodd, src->shape_count,
                     sizeof(*src->shape_evenodd), total, limit,
                     (void **)&dst->shape_evenodd) ||
        !clone_array(src->shape_filled, src->shape_count,
                     sizeof(*src->shape_filled), total, limit,
                     (void **)&dst->shape_filled) ||
        !clone_array(src->shape_edge_start, src->shape_count,
                     sizeof(*src->shape_edge_start), total, limit,
                     (void **)&dst->shape_edge_start) ||
        !clone_array(src->shape_edge_count, src->shape_count,
                     sizeof(*src->shape_edge_count), total, limit,
                     (void **)&dst->shape_edge_count)) goto fail;
    if (source->parent != NULL) {
        copy->parent = clone_clip_chain(source->parent, depth + 1U, total,
                                        limit);
        if (copy->parent == NULL) goto fail;
    }
    return copy;
fail:
    svg_clip_destroy(copy);
    return NULL;
}

svg_shape_clip *svg_clip_clone(const svg_shape_clip *clip,
                               size_t *total_bytes, bool *limit)
{
    if (total_bytes == NULL || limit == NULL) return NULL;
    *limit = false;
    return clone_clip_chain(clip, 0U, total_bytes, limit);
}

void svg_clip_update_owner(svg_shape_clip *clip, size_t owner_node,
                           geom_affine user_inverse,
                           geom_affine attribute_inverse,
                           const double local_bounds[4])
{
    size_t depth = 0U;
    for (svg_shape_clip *current = clip; current != NULL &&
         depth++ < CLIP_CLONE_MAX_DEPTH; current = current->parent) {
        if (current->owner_node != owner_node) continue;
        geom_affine inverse = current->owner_before_suffix ?
                              attribute_inverse : user_inverse;
        if (!geom_affine_valid(inverse)) continue;
        current->user_inverse = inverse;
        if (local_bounds != NULL && current->object_bounding_box &&
            isfinite(local_bounds[0]) && isfinite(local_bounds[1]) &&
            isfinite(local_bounds[2]) && isfinite(local_bounds[3]) &&
            local_bounds[2] >= local_bounds[0] &&
            local_bounds[3] >= local_bounds[1])
            memcpy(current->bounds, local_bounds, sizeof(current->bounds));
    }
}

bool svg_clip_local_bounds(const svg_shape_document *document,
                           size_t first_edge, size_t edge_count,
                           geom_affine user_inverse, double bounds[4])
{
    if (document == NULL || bounds == NULL || edge_count == 0U ||
        first_edge > document->edge_count ||
        edge_count > document->edge_count - first_edge) return false;
    geom_point first;
    if (!geom_affine_map_point(user_inverse, document->edges[first_edge].a,
                               &first)) return false;
    bounds[0] = bounds[2] = first.x;
    bounds[1] = bounds[3] = first.y;
    for (size_t i = first_edge; i < first_edge + edge_count; ++i) {
        geom_point points[2] = {document->edges[i].a, document->edges[i].b};
        for (size_t j = 0U; j < 2U; ++j) {
            geom_point local;
            if (!geom_affine_map_point(user_inverse, points[j], &local))
                return false;
            if (local.x < bounds[0]) bounds[0] = local.x;
            if (local.y < bounds[1]) bounds[1] = local.y;
            if (local.x > bounds[2]) bounds[2] = local.x;
            if (local.y > bounds[3]) bounds[3] = local.y;
        }
    }
    return true;
}

bool svg_clip_apply_group(svg_shape_document *document,
                          size_t first_shape, size_t end_shape,
                          svg_shape_clip *clip)
{
    if (document == NULL || clip == NULL || first_shape > end_shape ||
        end_shape > document->shape_count) return false;
    for (size_t i = first_shape; i < end_shape; ++i) {
        svg_shape_clip *root = document->clips[i];
        if (root == NULL) {
            if (!svg_clip_retain(clip)) return false;
            document->clips[i] = clip;
            continue;
        }
        svg_shape_clip *tail = root;
        while (true) {
            if (tail == clip) break;
            if (tail->parent == NULL) {
                if (!svg_clip_retain(clip)) return false;
                tail->parent = clip;
                break;
            }
            tail = tail->parent;
        }
    }
    return true;
}

svg_shape_clip *svg_clip_create_rect(geom_point p0, geom_point p1,
                                    geom_point p2, geom_point p3,
                                    geom_affine user_inverse,
                                    size_t owner_node)
{
    const geom_point points[4] = {p0, p1, p2, p3};
    for (size_t i = 0U; i < 4U; ++i)
        if (!geom_finite_point(points[i])) return NULL;
    svg_shape_clip *clip = svg_shape_calloc(1U, sizeof(*clip));
    if (clip == NULL) return NULL;
    svg_shape_document *geometry = &clip->geometry;
    geometry->edges = svg_shape_calloc(4U, sizeof(*geometry->edges));
    geometry->shape_evenodd = svg_shape_calloc(1U, sizeof(*geometry->shape_evenodd));
    geometry->shape_filled = svg_shape_calloc(1U, sizeof(*geometry->shape_filled));
    geometry->shape_edge_start = svg_shape_calloc(1U, sizeof(*geometry->shape_edge_start));
    geometry->shape_edge_count = svg_shape_calloc(1U, sizeof(*geometry->shape_edge_count));
    if (geometry->edges == NULL || geometry->shape_evenodd == NULL ||
            for (size_t i = 0U; i < 2U; ++i) {
                geom_point local;
                if (!geom_affine_map_point(inverse, points[i], &local))
                    return false;
                if (local.x < min_x) min_x = local.x;
                if (local.x > max_x) max_x = local.x;
                if (local.y < min_y) min_y = local.y;
                if (local.y > max_y) max_y = local.y;
            }
        }
    }
    if (!isfinite(min_x) || !isfinite(min_y) || !isfinite(max_x) ||
        !isfinite(max_y) || max_x <= min_x || max_y <= min_y) return false;
    bounds[0] = min_x;
    bounds[1] = min_y;
    bounds[2] = max_x - min_x;
    bounds[3] = max_y - min_y;
    return true;
}

static void sync_mask_work(shape_traversal *destination,
                           const shape_traversal *source)
{
    destination->references.lookup_probes = source->references.lookup_probes;
    destination->use_instances = source->use_instances;
    destination->reference_bytes = source->reference_bytes;
    destination->element_visits = source->element_visits;
    destination->transform_operations = source->transform_operations;
    destination->paint_token_visits = source->paint_token_visits;
    destination->paint_cache = source->paint_cache;
    destination->builder.command_count = source->builder.command_count;
    destination->builder.point_count = source->builder.point_count;
    destination->builder.decoded_image_pixels =
        source->builder.decoded_image_pixels;
    destination->builder.text_bytes = source->builder.text_bytes;
    destination->builder.text_glyphs = source->builder.text_glyphs;
    destination->builder.text_commands = source->builder.text_commands;
    destination->mask_instances = source->mask_instances;
    destination->pattern_instances = source->pattern_instances;
    destination->pattern_bytes = source->pattern_bytes;
    destination->marker_instances = source->marker_instances;
}

static bool append_mask(svg_shape_document *document,
                        const svg_shape_mask *mask, size_t *index,
                        svg_shape_diagnostic *diagnostic)
{
    if (document->mask_count >= SVG_SHAPE_MAX_MASKS ||
        document->mask_count == SIZE_MAX / sizeof(*document->masks)) {
        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT, mask->source_offset);
        return false;
    }
    size_t count = document->mask_count + 1U;
    if (count > SIZE_MAX / sizeof(*document->masks)) {
        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT, mask->source_offset);
        return false;
    }
    svg_shape_mask *grown = svg_shape_realloc(
        document->masks, count * sizeof(*grown));
    if (grown == NULL) {
        fail(diagnostic, SVG_SHAPE_ERROR_OOM, mask->source_offset);
        return false;
    }
    document->masks = grown;
    document->masks[document->mask_count] = *mask;
    *index = document->mask_count++;
    return true;
}

bool svg_shape_traverse_attach_mask(shape_traversal *traversal,
                                    size_t element, size_t group_index,
                                    const svg_css_paint *style,
                                    geom_affine transform)
{
    svg_xml_span value = {0};
    if (!svg_css_paint_value(style, SVG_CSS_MASK, &value) ||
        svg_css_keyword_equals(traversal->source, value, "none")) return true;
    svg_shape_document *document = traversal->builder.doc;
    if (group_index == SVG_SHAPE_NO_GROUP ||
        group_index >= document->opacity_group_count) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_INVALID_ARGUMENT,
             value.offset);
        return false;
    }
    svg_xml_span id;
    size_t mask_element = 0U;
    if (!parse_url_id(traversal->source, value, &id) ||
        !svg_reference_index_find(traversal->source, traversal->tokens,
                                  traversal->token_count,
                                  &traversal->references, id, &mask_element) ||
        !svg_shape_span_eq(traversal->source,
                           traversal->tokens[mask_element].local_name, "mask")) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
        return false;
    }
    for (size_t i = 0U; i < traversal->active_mask_depth; ++i) {
        if (traversal->active_masks[i] == mask_element) {
            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 traversal->tokens[mask_element].name.offset);
            return false;
        }
    }
    if (traversal->active_mask_depth >=
            sizeof(traversal->active_masks) / sizeof(traversal->active_masks[0]) ||
        traversal->mask_instances >= SHAPE_MASK_MAX_INSTANCES) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
             traversal->tokens[mask_element].name.offset);
        return false;
    }
    svg_shape_opacity_group *group = &document->opacity_groups[group_index];
    group->end_shape = document->shape_count;
    if (group->first_shape == group->end_shape) return true;
    double target_box[4];
    if (!target_bounds(document, group, transform, target_box)) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED, value.offset);
        return false;
    }
    size_t end = matching_end(traversal, mask_element);
    if (end == SIZE_MAX) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_XML,
             traversal->tokens[mask_element].name.offset);
        return false;
    }

    bool region_bbox = true;
    bool content_bbox = false;
    svg_xml_span units = {0};
    if (attr(traversal->source, traversal->tokens, traversal->token_count,
             mask_element, "maskUnits", &units)) {
        if (svg_shape_span_eq(traversal->source, units, "userSpaceOnUse"))
            region_bbox = false;
        else if (!svg_shape_span_eq(traversal->source, units,
                                    "objectBoundingBox")) {
            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 units.offset);
            return false;
        }
    }
    if (attr(traversal->source, traversal->tokens, traversal->token_count,
             mask_element, "maskContentUnits", &units)) {
        if (svg_shape_span_eq(traversal->source, units, "objectBoundingBox"))
                           traversal->viewport_height;
        if (!read_mask_region(traversal->source, region_value, present,
                              region_bbox, reference, region[i],
                              &region[i]) ||
            (i >= 2U && region[i] <= 0.0)) {
            fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER,
                 present ? region_value.offset :
                           traversal->tokens[mask_element].name.offset);
            return false;
        }
    }
    geom_affine box_map = {target_box[2], 0.0, 0.0, target_box[3],
                           target_box[0], target_box[1]};
    geom_affine content_transform = transform;
    geom_affine region_transform = transform;
    if (content_bbox &&
        !geom_affine_compose(transform, box_map, &content_transform)) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
        return false;
    }
    if (region_bbox &&
        !geom_affine_compose(transform, box_map, &region_transform)) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_NUMBER, value.offset);
        return false;
    }
    svg_css_paint mask_style;
    svg_css_error css_result = svg_css_compute(
        traversal->css, traversal->source, traversal->tokens,
        traversal->token_count, mask_element, NULL, &mask_style);
    if (css_result != SVG_CSS_OK) {
        fail(traversal->diagnostic,
             css_result == SVG_CSS_LIMIT ? SVG_SHAPE_ERROR_LIMIT :
             css_result == SVG_CSS_OOM ? SVG_SHAPE_ERROR_OOM :
             SVG_SHAPE_ERROR_UNSUPPORTED,
             traversal->tokens[mask_element].name.offset);
        return false;
    }
    bool luminance = true;
    svg_xml_span mask_type = {0};
    if (svg_css_paint_value(&mask_style, SVG_CSS_MASK_TYPE, &mask_type)) {
        if (svg_css_keyword_equals(traversal->source, mask_type, "alpha"))
            luminance = false;
        else if (!svg_css_keyword_equals(traversal->source, mask_type,
                                         "luminance")) {
            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 mask_type.offset);
            return false;
        }
    }
    svg_shape_document *content = svg_shape_calloc(1U, sizeof(*content));
    if (content == NULL) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_OOM,
             traversal->tokens[mask_element].name.offset);
        return false;
    }
    content->width = document->width;
    content->height = document->height;
    content->view_x = document->view_x;
    content->view_y = document->view_y;
    content->view_width = document->view_width;
    content->view_height = document->view_height;
    content->preserve_aspect = document->preserve_aspect;
    content->source = traversal->source;
    content->media_context = document->media_context;
    content->release_image = document->release_image;

    traversal->active_masks[traversal->active_mask_depth++] = mask_element;
    traversal->mask_instances++;
    shape_traversal nested = *traversal;
    nested.root_seen = true;
    nested.transform_node_capacity = 0U;
    nested.selection_element = SIZE_MAX;
    nested.opacity_group_depth = 0U;
    nested.opacity_group_capacity = 0U;
    nested.text_state = NULL;
    nested.text_depth = 0U;
    nested.builder.doc = content;
    nested.builder.traversal = &nested;
    nested.builder.edge_capacity = 0U;
    nested.builder.shape_capacity = 0U;
    nested.builder.subpath_capacity = 0U;
    nested.builder.path_segment_capacity = 0U;
    nested.builder.path_number_capacity = 0U;
    nested.builder.shape_index = 0U;
    nested.builder.transform_node = SVG_SHAPE_NO_TRANSFORM_NODE;
    nested.builder.transform = content_transform;
    nested.builder.viewport_width = traversal->viewport_width;
    nested.builder.viewport_height = traversal->viewport_height;
    nested.viewport_width = traversal->viewport_width;
    nested.viewport_height = traversal->viewport_height;
    if (!svg_shape_traverse_walk_range(&nested, mask_element + 1U, end,
                                       content_transform, &mask_style, 0U)) {
        sync_mask_work(traversal, &nested);
        traversal->active_mask_depth--;
        svg_shape_document_destroy(content);
        svg_shape_free(content);
        return false;
    }
    sync_mask_work(traversal, &nested);
    traversal->active_mask_depth--;
    svg_shape_mask mask = {
        .content = content,
        .luminance = luminance,
        .region_object_bounding_box = region_bbox,
        .custom_region = custom_region,
        .region = {region[0], region[1], region[2], region[3]},
        .region_transform = region_transform,
        .source_offset = traversal->tokens[mask_element].name.offset};
    size_t mask_index = SVG_SHAPE_NO_MASK;
    if (!append_mask(document, &mask, &mask_index, traversal->diagnostic)) {
        svg_shape_document_destroy(content);
        svg_shape_free(content);
        return false;
    }
    group = &document->opacity_groups[group_index];
    group->mask_index = mask_index;
    (void)element;
    return true;
}
static bool matrix_equal(geom_affine a, geom_affine b)
{
    return a.a == b.a && a.b == b.b && a.c == b.c && a.d == b.d &&
           a.e == b.e && a.f == b.f;
}

static void sync_work(shape_traversal *destination,
                      const shape_traversal *source)
{
    destination->references.lookup_probes = source->references.lookup_probes;
    destination->use_instances = source->use_instances;
    destination->reference_bytes = source->reference_bytes;
    destination->element_visits = source->element_visits;
    destination->transform_operations = source->transform_operations;
    destination->paint_token_visits = source->paint_token_visits;
    destination->paint_cache = source->paint_cache;
    destination->builder.command_count = source->builder.command_count;
    destination->builder.point_count = source->builder.point_count;
    destination->builder.decoded_image_pixels =
        source->builder.decoded_image_pixels;
    destination->builder.text_bytes = source->builder.text_bytes;
    destination->builder.text_glyphs = source->builder.text_glyphs;
    destination->builder.text_commands = source->builder.text_commands;
    destination->mask_instances = source->mask_instances;
    destination->pattern_instances = source->pattern_instances;
    destination->pattern_bytes = source->pattern_bytes;
    destination->marker_instances = source->marker_instances;
}

static bool parse_supported_attributes(base_bytes source,
                                       const svg_xml_token *tokens,
                                       size_t token_count, size_t element,
                                       svg_shape_diagnostic *diagnostic)
{
    static const char *const allowed[] = {
        "id", "class", "style", "x", "y", "width", "height",
        "patternUnits", "patternContentUnits", "patternTransform",
        "viewBox", "preserveAspectRatio"};
    for (size_t i = element + 1U;
         i < token_count && tokens[i].kind == SVG_XML_TOKEN_ATTRIBUTE; ++i) {
        bool found = false;
        if (tokens[i].prefix.length != 0U) {
            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 tokens[i].name.offset);
            return false;
        }
        for (size_t j = 0U; j < sizeof(allowed) / sizeof(allowed[0]); ++j)
            if (svg_shape_span_eq(source, tokens[i].local_name, allowed[j])) {
                found = true;
                break;
            }
        if (!found) {
            fail(diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 tokens[i].name.offset);
            return false;
        }
    }
    return true;
}

static bool append_pattern(svg_shape_document *document,
                           svg_shape_pattern pattern, size_t *index,
                           svg_shape_diagnostic *diagnostic)
{
    if (document->pattern_count >= SVG_SHAPE_MAX_PATTERNS ||
        document->pattern_count == SIZE_MAX / sizeof(*document->patterns)) {
        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT,
             pattern.definition_element);
        return false;
    }
    size_t count = document->pattern_count + 1U;
    if (count > SIZE_MAX / sizeof(*document->patterns)) {
        fail(diagnostic, SVG_SHAPE_ERROR_LIMIT,
             pattern.definition_element);
        return false;
    }
    svg_shape_pattern *grown = svg_shape_realloc(
        document->patterns, count * sizeof(*grown));
    if (grown == NULL) {
        fail(diagnostic, SVG_SHAPE_ERROR_OOM,
             pattern.definition_element);
        return false;
    }
    document->patterns = grown;
    document->patterns[document->pattern_count] = pattern;
    document->pattern_bytes += pattern.byte_count;
    *index = document->pattern_count++;
    return true;
}

static bool cached_pattern(const svg_shape_document *document,
                           size_t definition, uint32_t width, uint32_t height,
                           double tile_width, double tile_height,
                           geom_affine content_transform, size_t *index)
{
    for (size_t i = 0U; i < document->pattern_count; ++i) {
        const svg_shape_pattern *candidate = &document->patterns[i];
        if (candidate->definition_element == definition &&
            candidate->width == width && candidate->height == height &&
            candidate->tile_width == tile_width &&
            candidate->tile_height == tile_height &&
            matrix_equal(candidate->content_transform, content_transform)) {
            *index = i;
            return true;
        }
    }
    return false;
}

static bool decode_pattern_content(shape_traversal *traversal,
                                   size_t definition, size_t end,
                                   geom_affine content_transform,
                                   double tile_width, double tile_height,
                                   uint32_t width, uint32_t height,
                                   size_t *pattern_index)
{
    svg_shape_document *owner = traversal->builder.doc;
    if (traversal->active_pattern_depth >=
            sizeof(traversal->active_patterns) /
                sizeof(traversal->active_patterns[0]) ||
        traversal->pattern_instances >= SHAPE_PATTERN_MAX_INSTANCES) {
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_LIMIT,
             traversal->tokens[definition].name.offset);
        return false;
    }
    for (size_t i = 0U; i < traversal->active_pattern_depth; ++i) {
        if (traversal->active_patterns[i] == definition) {
            fail(traversal->diagnostic, SVG_SHAPE_ERROR_UNSUPPORTED,
                 traversal->tokens[definition].name.offset);
            return false;
        }
    }
    traversal->active_patterns[traversal->active_pattern_depth++] = definition;
    traversal->pattern_instances++;
    svg_shape_document *content = svg_shape_calloc(1U, sizeof(*content));
    if (content == NULL) {
        traversal->active_pattern_depth--;
        fail(traversal->diagnostic, SVG_SHAPE_ERROR_OOM,
             traversal->tokens[definition].name.offset);
        return false;
    }
    content->width = width;
    content->height = height;
    content->view_x = 0.0;
    content->view_y = 0.0;
    content->view_width = tile_width;
    content->view_height = tile_height;
    content->preserve_aspect = (svg_shape_aspect){
        0.0, 0.0, true, false, true};
    content->source = traversal->source;
    content->media_context = owner->media_context;
    content->release_image = owner->release_image;
    svg_css_paint pattern_style;
    svg_css_error css_result = svg_css_compute(
        traversal->css, traversal->source, traversal->tokens,
        traversal->token_count, definition, NULL, &pattern_style);
    if (css_result != SVG_CSS_OK) {
        traversal->active_pattern_depth--;
        svg_shape_document_destroy(content);
        svg_shape_free(content);
        fail(traversal->diagnostic,
             css_result == SVG_CSS_LIMIT ? SVG_SHAPE_ERROR_LIMIT :
             css_result == SVG_CSS_OOM ? SVG_SHAPE_ERROR_OOM :
             SVG_SHAPE_ERROR_UNSUPPORTED,
             traversal->tokens[definition].name.offset);
        return false;
    }
    shape_traversal nested = *traversal;
    nested.root_seen = true;
    nested.transform_node_capacity = 0U;
    nested.selection_element = SIZE_MAX;

//! Clip geometry, queries and safe scene mutation adapters.
use vexel_base::WorkControl;
use vexel_geometry::{affine_map_point, affine_valid};
use vexel_scene::*;

pub const MAX_CLIP_CHILDREN: usize = 64;
pub const MAX_CLIP_DEPTH: usize = 256;
pub const MAX_CLIP_REFERENCE_BYTES: usize = 64 * 1024;
pub const MAX_CLIP_JOB_REFERENCE_BYTES: usize = 512 * 1024;
pub const CLIP_WRAPPER_BUFFER_BYTES: usize = 192;
pub const CLIP_WRAPPER_LIMIT_BYTES: usize = 4096;
pub const CLIP_WRAPPER_WORST_BYTES: usize = 155;
pub const MAX_CLIP_EDGES: usize = 65536;
pub const MAX_CLIP_CLONE_DEPTH: usize = 64;
pub const MAX_CLIP_CLONE_BYTES: usize = 64 * 1024 * 1024;
const _: () = assert!(CLIP_WRAPPER_BUFFER_BYTES <= CLIP_WRAPPER_LIMIT_BYTES);
const _: () = assert!(CLIP_WRAPPER_WORST_BYTES <= CLIP_WRAPPER_BUFFER_BYTES);

pub fn create_rect(
    points: [Point; 4],
    user_inverse: Affine,
    owner_node: Option<TransformId>,
    builder: &mut SceneBuilder,
    scene: SceneId,
    control: &mut dyn WorkControl,
) -> Result<ClipId> {
    if !affine_valid(user_inverse) || points.iter().any(|p| !p.x.is_finite() || !p.y.is_finite()) {
        return Err(Diagnostic {
            kind: ErrorKind::InvalidArgument,
            offset: 0,
        });
    }
    if 4 > MAX_CLIP_EDGES {
        return Err(limit());
    }
    let mut edges = Vec::new();
    edges.try_reserve_exact(4).map_err(|_| oom())?;
    for i in 0..4 {
        edges.push(Edge {
            a: points[i],
            b: points[(i + 1) % 4],
        });
    }
    let mut shapes = Vec::new();
    shapes.try_reserve_exact(1).map_err(|_| oom())?;
    shapes.push(ClipChild {
        edges: TableRange { first: 0, count: 4 },
        evenodd: false,
        filled: true,
    });
    let (mut lo_x, mut lo_y, mut hi_x, mut hi_y) =
        (points[0].x, points[0].y, points[0].x, points[0].y);
    for p in points.iter().skip(1) {
        lo_x = lo_x.min(p.x);
        lo_y = lo_y.min(p.y);
        hi_x = hi_x.max(p.x);
        hi_y = hi_y.max(p.y);
    }
    builder.append_clip(
        scene,
        Clip {
            geometry: ClipGeometry { edges, shapes },
            parent: None,
            owner_node,
            owner_before_suffix: true,
            object_bounding_box: false,
            bounds: [lo_x, lo_y, hi_x, hi_y],
            user_inverse,
        },
        control,
    )
}

pub fn contains(view: SceneView<'_>, clip: ClipId, x: f64, y: f64) -> bool {
    let (mut next, mut depth) = (Some(clip), 0usize);
    while let Some(id) = next {
        if depth >= MAX_CLIP_DEPTH {
            return false;
        }
        let Some(c) = view.clip(id) else { return false };
        let Some(p) = affine_map_point(c.user_inverse, Point { x, y }) else {
            return false;
        };
        let (mut px, mut py) = (p.x, p.y);
        if c.object_bounding_box {
            let [x0, y0, x1, y1] = c.bounds;
            if x1 <= x0 || y1 <= y0 {
                return false;
            }
            px = (px - x0) / (x1 - x0);
            py = (py - y0) / (y1 - y0);
        }
        if !c.geometry.shapes.iter().any(|child| {
            child.filled && point_inside(&c.geometry.edges, child.edges, child.evenodd, px, py)
        }) {
            return false;
        }
        next = c.parent;
        depth += 1;
    }
    true
}
fn point_inside(edges: &[Edge], range: TableRange, evenodd: bool, x: f64, y: f64) -> bool {
    let Some(slice) = range.slice(edges) else {
        return false;
    };
    let (mut winding, mut parity) = (0i32, false);
    for e in slice {
        let up = e.a.y <= y && e.b.y > y;
        let down = e.b.y <= y && e.a.y > y;
        if !up && !down {
            continue;
        }
        let cross = e.a.x + (y - e.a.y) * (e.b.x - e.a.x) / (e.b.y - e.a.y);
        if cross > x {
            winding += if up { 1 } else { -1 };
            parity = !parity;
        }
    }
    if evenodd { parity } else { winding != 0 }
}

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct ClipWorkCounts {
    pub chain_elements: usize,
    pub child_shapes: usize,
    pub edges: usize,
}
pub fn work_counts(view: SceneView<'_>, clip: ClipId) -> Result<ClipWorkCounts> {
    let mut out = ClipWorkCounts::default();
    let (mut next, mut depth) = (Some(clip), 0);
    while let Some(id) = next {
        if depth >= MAX_CLIP_DEPTH {
            return Err(limit());
        }
        let c = view.clip(id).ok_or_else(invalid)?;
        out.chain_elements = out.chain_elements.checked_add(1).ok_or_else(arithmetic)?;
        out.child_shapes = out
            .child_shapes
            .checked_add(c.geometry.shapes.len())
            .ok_or_else(arithmetic)?;
        out.edges = out
            .edges
            .checked_add(c.geometry.edges.len())
            .ok_or_else(arithmetic)?;
        next = c.parent;
        depth += 1;
    }
    Ok(out)
}
pub fn work_units(view: SceneView<'_>, clip: ClipId) -> Result<usize> {
    let c = work_counts(view, clip)?;
    c.chain_elements
        .checked_add(c.child_shapes)
        .and_then(|x| x.checked_add(c.edges))
        .ok_or_else(arithmetic)
}
pub fn local_bounds(edges: &[Edge], inverse: Affine) -> Option<[f64; 4]> {
    if edges.is_empty() {
        return None;
    }
    let first = affine_map_point(inverse, edges[0].a)?;
    let mut b = [first.x, first.y, first.x, first.y];
    for e in edges {
        for p in [e.a, e.b] {
            let q = affine_map_point(inverse, p)?;
            b[0] = b[0].min(q.x);
            b[1] = b[1].min(q.y);
            b[2] = b[2].max(q.x);
            b[3] = b[3].max(q.y);
        }
    }
    Some(b)
}

/// Visits document-space edges. `Ok(false)` means the visitor stopped; an invalid
/// mapping is reported separately so callers disable culling conservatively.
pub fn visit_boundary_edges(
    view: SceneView<'_>,
    clip: ClipId,
    mut visitor: impl FnMut(Edge) -> bool,
) -> Result<(bool, bool)> {
    let (mut id, mut valid, mut depth) = (Some(clip), true, 0);
    while let Some(cid) = id {
        if depth >= MAX_CLIP_DEPTH {
            return Err(limit());
        }
        let c = view.clip(cid).ok_or_else(invalid)?;
        let Some(local_to_doc) = inverse_affine(c.user_inverse) else {
            return Ok((true, false));
        };
        for child in &c.geometry.shapes {
            if !child.filled {
                continue;
            }
            let Some(edges) = child.edges.slice(&c.geometry.edges) else {
                return Err(invalid());
            };
            for mut edge in edges.iter().copied() {
                for p in [&mut edge.a, &mut edge.b] {
                    let mut q = *p;
                    if c.object_bounding_box {
                        q.x = c.bounds[0] + q.x * (c.bounds[2] - c.bounds[0]);
                        q.y = c.bounds[1] + q.y * (c.bounds[3] - c.bounds[1]);
                    }
                    let Some(mapped) = affine_map_point(local_to_doc, q) else {
                        valid = false;
                        return Ok((true, valid));
                    };
                    *p = mapped;
                }
                if !visitor(edge) {
                    return Ok((false, valid));
                }
            }
        }
        id = c.parent;
        depth += 1;
    }
    Ok((true, valid))
    Ok((true, valid))
}

/// Appends a per-shape child clip and finalizes each new shape inside the caller's
/// real draft. Existing clip records remain immutable and shared safely.
pub fn apply_group(
    builder: &mut SceneBuilder,
    token: &DraftToken,
    scene: SceneId,
    shape_ids: &[ShapeId],
    clip: ClipId,
    control: &mut dyn WorkControl,
) -> Result<()> {
    if shape_ids.is_empty() {
        return Ok(());
    }
    if shape_ids.len() > MAX_CLIP_CLONE_BYTES / std::mem::size_of::<(ClipId, ClipId)>() {
        return Err(limit());
    }
    let mut root_cache = Vec::<(ClipId, ClipId)>::new();
    root_cache.try_reserve(shape_ids.len()).map_err(|_| oom())?;
    let mut copied_bytes = 0usize;
    for id in shape_ids {
        control.checkpoint().map_err(stopped)?;
        let old = builder
            .scene(scene)?
            .shape(*id)
            .copied()
            .ok_or_else(invalid)?;
        let appended = if let Some(old_root) = old.clip {
            if chain_contains(builder.scene(scene)?, old_root, clip, control)? {
                continue;
            }
            if let Some((_, copied_root)) =
                root_cache.iter().find(|(source, _)| *source == old_root)
            {
                *copied_root
            } else {
                let copied_root = append_clip_chain(
                    builder,
                    scene,
                    old_root,
                    Some(clip),
                    control,
                    &mut copied_bytes,
                )?;
                root_cache.push((old_root, copied_root));
                copied_root
            }
        } else {
            clip
        };
        let mut shape = old;
        shape.clip = Some(appended);
        builder.finalize_shape(token, *id, shape, control)?;
    }
    Ok(())
}
fn chain_contains(
    view: SceneView<'_>,
    root: ClipId,
    target: ClipId,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    let mut next = Some(root);
    let mut depth = 0usize;
    while let Some(id) = next {
        control.checkpoint().map_err(stopped)?;
        if depth >= MAX_CLIP_CLONE_DEPTH {
            return Err(limit());
        }
        if id == target {
            return Ok(true);
        }
        let clip = view.clip(id).ok_or_else(invalid)?;
        control.charge(WorkKind::ClipChain, 1).map_err(stopped)?;
        next = clip.parent;
        depth += 1;
    }
    Ok(false)
}
fn append_clip_chain(
    builder: &mut SceneBuilder,
    scene: SceneId,
    root: ClipId,
    parent: Option<ClipId>,
    control: &mut dyn WorkControl,
    copied_bytes: &mut usize,
) -> Result<ClipId> {
    let mut chain = Vec::new();
    chain
        .try_reserve_exact(MAX_CLIP_CLONE_DEPTH)
        .map_err(|_| oom())?;
    let mut next = Some(root);
    while let Some(id) = next {
        control.checkpoint().map_err(stopped)?;
        if chain.len() >= MAX_CLIP_CLONE_DEPTH {
            return Err(limit());
        }
        let view = builder.scene(scene)?;
        let clip = view.clip(id).ok_or_else(invalid)?;
        let work = clip
            .geometry
            .edges
            .len()
            .checked_add(clip.geometry.shapes.len())
            .and_then(|n| n.checked_add(1))
            .ok_or_else(arithmetic)?;
        control
            .charge(
                WorkKind::ClipEdge,
                u64::try_from(work).map_err(|_| arithmetic())?,
            )
            .map_err(stopped)?;
        chain.push(id);
        next = clip.parent;
    }
    let mut parent = parent;
    let mut result = None;
    for id in chain.into_iter().rev() {
        let mut copy = {
            let view = builder.scene(scene)?;
            let source = view.clip(id).ok_or_else(invalid)?;
            clone_clip_geometry(source)?
        };
        copy.parent = parent;
        let actual = copy
            .geometry
            .edges
            .capacity()
            .checked_mul(std::mem::size_of::<Edge>())
            .and_then(|n| {
                copy.geometry
                    .shapes
                    .capacity()
                    .checked_mul(std::mem::size_of::<ClipChild>())
                    .and_then(|m| n.checked_add(m))
            })
            .ok_or_else(arithmetic)?;
        *copied_bytes = copied_bytes
            .checked_add(actual)
            .filter(|n| *n <= MAX_CLIP_CLONE_BYTES)
            .ok_or_else(limit)?;
        let appended = builder.append_clip(scene, copy, control)?;
        parent = Some(appended);
        result = Some(appended);
    }
    result.ok_or_else(invalid)
}
fn clone_clip_geometry(c: &Clip) -> Result<Clip> {
    let mut edges = Vec::new();
    edges
        .try_reserve_exact(c.geometry.edges.len())
        .map_err(|_| oom())?;
    edges.extend_from_slice(&c.geometry.edges);
    let mut shapes = Vec::new();
    shapes
        .try_reserve_exact(c.geometry.shapes.len())
        .map_err(|_| oom())?;
    shapes.extend_from_slice(&c.geometry.shapes);
    Ok(Clip {
        geometry: ClipGeometry { edges, shapes },
        parent: None,
        owner_node: c.owner_node,
        owner_before_suffix: c.owner_before_suffix,
        object_bounding_box: c.object_bounding_box,
        bounds: c.bounds,
        user_inverse: c.user_inverse,
    })
}
fn invalid() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::InvalidArgument,
        offset: 0,
    }
}
fn limit() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Edges),
        offset: 0,
    }
}
fn arithmetic() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::Limit(LimitKind::Arithmetic),
        offset: 0,
    }
}
fn oom() -> Diagnostic {
    Diagnostic {
        kind: ErrorKind::OutOfMemory,
        offset: 0,
    }
}
fn stopped(s: vexel_base::Stop) -> Diagnostic {
    Diagnostic {
        kind: match s {
            vexel_base::Stop::Canceled => ErrorKind::Canceled,
            vexel_base::Stop::Limit => ErrorKind::Limit(LimitKind::Work),
            vexel_base::Stop::Overflow => ErrorKind::Limit(LimitKind::Arithmetic),
        },
        offset: 0,
    }
}

pub fn inverse_affine(m: Affine) -> Option<Affine> {
    if !affine_valid(m) {
        return None;
    }
    let det = m.a * m.d - m.b * m.c;
    if !det.is_finite() || det == 0.0 {
    if !det.is_finite() || det == 0.0 {
        return None;
    }
    let v = Affine {
        a: m.d / det,
        b: -m.b / det,
        c: -m.c / det,
        d: m.a / det,
        e: (m.c * m.f - m.d * m.e) / det,
        f: (m.b * m.e - m.a * m.f) / det,
    };
    affine_valid(v).then_some(v)
}

/// Maps one clip-local point into document coordinates, including the target's
/// object-bounding-box normalization when present.
pub fn local_to_document(view: SceneView<'_>, clip: ClipId, point: Point) -> Option<Point> {
    let c = view.clip(clip)?;
    let mut point = point;
    if c.object_bounding_box {
        let [x0, y0, x1, y1] = c.bounds;
        if x1 <= x0 || y1 <= y0 {
            return None;
        }
        point.x = x0 + point.x * (x1 - x0);
        point.y = y0 + point.y * (y1 - y0);
    }
    affine_map_point(inverse_affine(c.user_inverse)?, point)
}

#[derive(Debug, Default)]
pub struct ClipOverlay {
    entries: Vec<(ClipId, Clip)>,
}
impl ClipOverlay {
    pub fn len(&self) -> usize {
        self.entries.len()
    }
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
    pub fn get(&self, id: ClipId) -> Option<&Clip> {
        self.entries
            .iter()
            .find_map(|(key, clip)| (*key == id).then_some(clip))
    }
    pub fn iter(&self) -> impl Iterator<Item = (ClipId, &Clip)> {
        self.entries.iter().map(|(id, clip)| (*id, clip))
    }
    pub fn allocated_bytes(&self) -> Option<usize> {
        let mut n = self
            .entries
            .capacity()
            .checked_mul(std::mem::size_of::<(ClipId, Clip)>())?;
        for (_, c) in &self.entries {
            n = n.checked_add(
                c.geometry
                    .edges
                    .capacity()
                    .checked_mul(std::mem::size_of::<Edge>())?,
            )?;
            n = n.checked_add(
                c.geometry
                    .shapes
                    .capacity()
                    .checked_mul(std::mem::size_of::<ClipChild>())?,
            )?;
        }
        Some(n)
    }
}
/// Copies requested clip graphs into owned, deduplicated Rust storage. IDs are
/// keys only; no pointer/refcount ownership crosses the overlay boundary.
pub fn clone_clips(
    view: SceneView<'_>,
    roots: &[ClipId],
    control: &mut dyn WorkControl,
) -> Result<ClipOverlay> {
    let mut out = ClipOverlay::default();
    let maximum_roots = MAX_CLIP_CLONE_BYTES / std::mem::size_of::<(ClipId, Clip)>();
    if roots.len() > maximum_roots {
        return Err(limit());
    }
    out.entries.try_reserve(roots.len()).map_err(|_| oom())?;
    if out
        .allocated_bytes()
        .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
    {
        return Err(limit());
    }
    for root in roots {
        let (mut next, mut depth) = (Some(*root), 0);
        while let Some(id) = next {
            control.checkpoint().map_err(stopped)?;
            if out.entries.iter().any(|(seen, _)| seen == &id) {
                break;
            }
            if depth >= MAX_CLIP_CLONE_DEPTH {
                return Err(limit());
            }
            let c = view.clip(id).ok_or_else(invalid)?;
            let copy_bytes = c
                .geometry
                .edges
                .len()
                .checked_mul(std::mem::size_of::<Edge>())
                .and_then(|n| {
                    c.geometry
                        .shapes
                        .len()
                        .checked_mul(std::mem::size_of::<ClipChild>())
                        .and_then(|m| n.checked_add(m))
                })
                .ok_or_else(arithmetic)?;
            let current_bytes = out.allocated_bytes().ok_or_else(arithmetic)?;
            if current_bytes
                .checked_add(copy_bytes)
                .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
            {
                return Err(limit());
            }
            let work = c
                .geometry
                .edges
                .len()
                .checked_add(c.geometry.shapes.len())
                .and_then(|n| n.checked_add(1))
                .ok_or_else(arithmetic)?;
            control
                .charge(
                    WorkKind::TokenVisit,
                    u64::try_from(work).map_err(|_| arithmetic())?,
                )
                .map_err(stopped)?;
            let mut edges = Vec::new();
            edges
                .try_reserve_exact(c.geometry.edges.len())
                .map_err(|_| oom())?;
            edges.extend_from_slice(&c.geometry.edges);
            let mut shapes = Vec::new();
            shapes
                .try_reserve_exact(c.geometry.shapes.len())
                .map_err(|_| oom())?;
            shapes.extend_from_slice(&c.geometry.shapes);
            let clone = Clip {
                geometry: ClipGeometry { edges, shapes },
                parent: c.parent,
                owner_node: c.owner_node,
                owner_before_suffix: c.owner_before_suffix,
                object_bounding_box: c.object_bounding_box,
                bounds: c.bounds,
                user_inverse: c.user_inverse,
            };
            out.entries.try_reserve(1).map_err(|_| oom())?;
            out.entries.push((id, clone));
            if out
                .allocated_bytes()
                .is_none_or(|n| n > MAX_CLIP_CLONE_BYTES)
            {
                return Err(limit());
            }
            next = c.parent;
            depth += 1;
        }
    }
    Ok(out)
}
/// Updates every matching owner on one chain. Bounds change only for valid
/// object-box bounds; an invalid inverse leaves the previous mapping intact.
pub fn update_owner(
    overlay: &mut ClipOverlay,
    id: ClipId,
    owner: TransformId,
    user_inverse: Affine,
    attribute_inverse: Affine,
    bounds: [f64; 4],
) -> Result<()> {
    let mut current = Some(id);
    let mut depth = 0;
    while let Some(key) = current {
        if depth >= MAX_CLIP_CLONE_DEPTH {
            return Err(limit());
        }
        let Some((_, clip)) = overlay.entries.iter_mut().find(|(k, _)| *k == key) else {
            return Err(invalid());
        };
        if clip.owner_node == Some(owner) {
            let candidate = if clip.owner_before_suffix {
                attribute_inverse
            } else {
                user_inverse
            };
            if affine_valid(candidate) {
                clip.user_inverse = candidate;
                if clip.object_bounding_box
                    && bounds.iter().all(|x| x.is_finite())
                    && bounds[2] >= bounds[0]
                    && bounds[3] >= bounds[1]
                {
                    clip.bounds = bounds;
                }
            }
        }
        current = clip.parent;
        depth += 1;
    }
    Ok(())
}

